void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    ivec2 xy = ivec2(fragCoord.xy);

    int x = xy.x;
    int y = xy.y;

    int a = (x + y) & (y - x);
    int b = (y - x) ^ (x - y);
    int c = (b != 0) ? (a / b) % 256 : 0;

    vec3 color = vec3(0.);

    if ((a & b) % 13 == 0) {
        color.r = abs(sin(float(a))) * 1.;
        color.g = abs(sin(float(b))) * 1.;
        color.b = abs(sin(float(c))) * 1.;
    }

    int dx = x - int(iResolution.x / 2.);
    int dy = y - int(iResolution.y / 2.);
    int distSquared = dx * dx + dy * dy;

    if (distSquared <= 128 * 128) {
        color = vec3(
            float((x ^ y) % 255) / 255.,
            float((x | y) % 255) / 255.,
            float((x & y) % 255) / 255.
        );
    } 
    else if ((x & y) % 5 == 0) {
        color = vec3(
            float((x | y) % 255) / 255.,
            float((x & y) % 255) / 255.,
            float((x ^ y) % 255) / 255.
        );
    }

    fragColor = vec4(color, 1.);
}
